// bbx fixture: MCP stdio server whose one tool describes how it was started.
// --user-data-dir=<dir>/pilotdeck-mcp-<id>-XXXXXX has a random suffix: only the
// directory and the stable prefix are reported, plus whether the dir exists.
import readline from 'node:readline';
import fs from 'node:fs';
import path from 'node:path';
const args = process.argv.slice(2).map((arg) => {
  if (!arg.startsWith('--user-data-dir=')) return arg;
  const dir = arg.slice('--user-data-dir='.length);
  return '--user-data-dir=' + path.dirname(dir) + '/' + path.basename(dir).slice(0, -6) + '<rand> exists=' + fs.existsSync(dir);
});
const env = ['PILOTDECK_SESSION_STORAGE_ROOT', 'PILOTDECK_SESSION_TMPDIR', 'BBX_LABEL'].map((k) => k + '=' + (process.env[k] ?? '-'));
const label = JSON.stringify({ args, env, cwd: process.cwd() });
const send = (message) => process.stdout.write(JSON.stringify(message) + '\n');
const tool = { name: 'probe', description: 'started with ' + label, inputSchema: { type: 'object', properties: {}, additionalProperties: false } };
readline.createInterface({ input: process.stdin }).on('line', (line) => {
  let request;
  try { request = JSON.parse(line); } catch { return; }
  if (request.id === undefined) return;
  if (request.method === 'initialize') {
    send({ jsonrpc: '2.0', id: request.id, result: { protocolVersion: request.params?.protocolVersion ?? '2024-11-05', capabilities: { tools: {} }, serverInfo: { name: 'bbx-probe', version: '1.0.0' } } });
  } else if (request.method === 'tools/list') {
    send({ jsonrpc: '2.0', id: request.id, result: { tools: [tool] } });
  } else if (request.method === 'tools/call') {
    send({ jsonrpc: '2.0', id: request.id, result: { content: [{ type: 'text', text: label }] } });
  } else {
    send({ jsonrpc: '2.0', id: request.id, result: {} });
  }
});
